from pathlib import Path
import json,re
B=Path(__file__).resolve().parent
p=B/'output/Rheinmetall_Portfolioanalyse.html'
s=p.read_text()
f=json.loads((B/'work/portfolio-reviewed.json').read_text());a=json.loads((B/'work/positioning-portfolio.json').read_text())
ratings={x['product_id']:x for x in a['interpretations']}
data=[{'id':x['id'],'label':x.get('short_label',x['label']),'domain':x['domain'],'grade':ratings[x['id']]['score']} for x in f['products']]
assert len(data)==69
widget='''<section class="module donut-module"><div class="donut-top"><div><div class="page-kicker">01 / PORTFOLIOREIFE AUF EINEN BLICK</div><h2>So verteilt sich die öffentlich belegte Reife.</h2></div><label>Kategorie<select id="donut-domain"><option value="">Gesamtes Portfolio</option></select></label></div><div class="donut-kpis"><span><b id="donut-established">31 / 69</b> im Betrieb oder in Serie</span><span><b id="donut-open">24</b> mit offener Beleglage</span><span class="donut-basis">Anzahl erfasster Objekte · keine Umsatzanteile oder Gesamtnote</span></div><div class="donut-layout"><div class="donut-figure"><svg id="maturity-donut" viewBox="0 0 320 320" aria-label="Verteilung der öffentlich belegten Produktreife" role="group"></svg></div><div class="donut-legend" id="donut-legend" aria-label="Nach Reifestufe filtern"></div><div class="donut-products"><div class="donut-products-head"><h3 id="donut-products-title">Im Betrieb</h3><button id="donut-all" type="button">Alle anzeigen</button></div><div class="donut-product-list" id="donut-product-list"></div><p class="meta">Segment oder Zeile wählen. Produkt anklicken für Bewertung und Originalbelege.</p></div></div><p class="donut-foot">Die Stufe zeigt den höchsten konkret belegten Meilenstein. „Offen“ bedeutet fehlende eindeutige Evidenz, keine niedrige Produktreife. Varianten werden getrennt gezählt.</p></section>'''
css='''<style>
.donut-module{padding:17px 22px!important}.donut-top{display:flex;justify-content:space-between;align-items:center;gap:18px}.donut-top .page-kicker{margin:0 0 4px}.donut-top h2{border:0;padding:0;margin:0;font-size:23px}.donut-top label{display:grid;gap:3px;font-size:11px;color:#607887;flex:none}.donut-top select{min-width:230px;border:1px solid #d5e0e6;border-radius:6px;background:#f6f9fa;padding:8px 10px;color:#173345}.donut-kpis{display:flex;align-items:baseline;gap:23px;flex-wrap:wrap;padding:10px 0 11px;border-bottom:1px solid #dce5e9;font-size:12px;color:#607887}.donut-kpis b{font-size:21px;color:#154c61;margin-right:5px;font-variant-numeric:tabular-nums}.donut-kpis .donut-basis{margin-left:auto;font-size:11px}.donut-layout{display:grid;grid-template-columns:300px minmax(225px,.8fr) minmax(300px,1.3fr);gap:19px;align-items:center;padding:10px 0}.donut-figure svg{display:block;width:100%;height:auto}.donut-slice{cursor:pointer;transition:opacity .15s}.donut-slice:hover{opacity:.78}.donut-slice:focus{outline:none;stroke:#c3872d;stroke-width:4}.donut-slice.selected{stroke:#173345;stroke-width:3}.donut-legend{display:grid;gap:4px}.donut-legend button{display:grid;grid-template-columns:9px 1fr 28px 44px;align-items:center;gap:8px;text-align:left;border:1px solid transparent;background:#f5f8fa;border-radius:6px;padding:8px 10px;color:#173345;font-size:12px}.donut-legend button[aria-pressed="true"]{border-color:#769eaf;background:#eaf2f5}.donut-legend button:disabled{opacity:.48;cursor:default}.donut-legend i{width:9px;height:9px;border-radius:3px}.donut-legend b,.donut-legend em{text-align:right;font-variant-numeric:tabular-nums}.donut-legend em{font-style:normal;color:#607887;font-size:11px}.donut-products{align-self:stretch;display:flex;flex-direction:column;min-width:0;border-left:1px solid #dce5e9;padding-left:18px}.donut-products-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:4px 0 9px}.donut-products-head h3{margin:0;font-size:15px}.donut-products-head button{border:0;background:#eaf1f4;color:#154c61;padding:5px 8px;border-radius:5px;font-size:11px;white-space:nowrap}.donut-product-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;gap:6px;max-height:241px;overflow:auto;padding-right:5px}.donut-product-list a{display:flex;align-items:center;gap:7px;text-decoration:none;border:1px solid #dce5e9;border-left:3px solid var(--grade);border-radius:5px;background:#f7fafb;padding:7px 8px;font-size:11px;line-height:1.35;min-height:37px}.donut-product-list a:hover{background:#eaf2f5}.donut-product-list a span{margin-left:auto;color:#607887;flex:none}.donut-products .meta{font-size:10px;margin:8px 0 0}.donut-foot{font-size:11px!important;color:#607887;border-top:1px solid #dce5e9;padding-top:8px;margin:0!important}.matrix-disclosure>summary{font-size:15px;font-weight:700;color:#154c61}.matrix-disclosure[open]>summary{margin-bottom:15px}.mast>div{padding-top:15px;padding-bottom:15px}.mast h1{font-size:28px}.mast p{font-size:13px}.tabs{padding-top:7px;padding-bottom:7px}main{padding-top:14px}.page>.page-kicker{margin-bottom:10px}
@media(max-width:1100px){.donut-layout{grid-template-columns:280px 1fr}.donut-products{grid-column:1/-1;border-left:0;border-top:1px solid #dce5e9;padding:12px 0 0}.donut-product-list{grid-template-columns:repeat(4,minmax(0,1fr));max-height:155px}.donut-kpis .donut-basis{margin-left:0}}
@media(max-width:650px){.donut-top{align-items:stretch;flex-direction:column;gap:9px}.donut-top h2{font-size:20px}.donut-layout{grid-template-columns:1fr;gap:6px}.donut-figure{max-width:290px;width:100%;margin:auto}.donut-product-list{grid-template-columns:repeat(2,minmax(0,1fr));max-height:200px}.donut-kpis{gap:6px 16px}.donut-module{padding:15px!important}.donut-products{grid-column:auto}.donut-kpis b{font-size:19px}}
@media print{.donut-top select,.donut-all{display:none}.donut-layout{grid-template-columns:230px 200px 1fr;gap:12px}.donut-product-list{max-height:none;overflow:visible;display:block}.donut-product-list a{display:none}.donut-products{display:none}.donut-legend button{print-color-adjust:exact}.donut-module{break-inside:avoid}.matrix-disclosure>summary{display:none}.matrix-disclosure:not([open])>:not(summary){display:block!important}}
</style>'''
js='''<script id="donut-script">(()=>{
const data=__DATA__,labels={'1':'Angekündigt','2':'Prototyp','3':'Test / Demo','4':'Kundenprogramm','5':'Im Betrieb','6':'Serie / Skala','open':'Beleglage offen'},colors={'1':'#ba8e4d','2':'#8b7fba','3':'#669fba','4':'#2f8492','5':'#15596b','6':'#387b59','open':'#bbc6ce'},order=['1','2','3','4','5','6','open'];let selected='5';
const svg=document.getElementById('maturity-donut'),domain=document.getElementById('donut-domain'),legend=document.getElementById('donut-legend'),list=document.getElementById('donut-product-list');
for(const name of [...new Set(data.map(x=>x.domain))]){const opt=document.createElement('option');opt.value=opt.textContent=name;domain.append(opt);}
const key=p=>p.grade===null?'open':String(p.grade),el=(tag,attr={},text)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attr))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n;};
function render(){const rows=data.filter(p=>!domain.value||p.domain===domain.value),total=rows.length,counts=Object.fromEntries(order.map(k=>[k,rows.filter(p=>key(p)===k).length]));document.getElementById('donut-established').textContent=(counts['5']+counts['6'])+' / '+total;document.getElementById('donut-open').textContent=counts.open;svg.replaceChildren();legend.replaceChildren();let angle=-Math.PI/2;const point=(r,a)=>[160+r*Math.cos(a),160+r*Math.sin(a)];
for(const k of order){const n=counts[k],percent=total?n/total*100:0;if(n){const end=angle+2*Math.PI*n/total,start=point(144,angle),stop=point(144,end),innerEnd=point(66,end),innerStart=point(66,angle),large=end-angle>Math.PI?1:0;let d;if(n===total){d='M160 16 A144 144 0 1 1 159.99 16 L159.99 94 A66 66 0 1 0 160 94 Z';}else d=`M${start} A144 144 0 ${large} 1 ${stop} L${innerEnd} A66 66 0 ${large} 0 ${innerStart} Z`;const path=el('path',{d,fill:colors[k],stroke:'#fff','stroke-width':2,class:'donut-slice'+(selected===k?' selected':''),role:'button',tabindex:0,'aria-label':labels[k]+': '+n+' Objekte, '+percent.toFixed(1)+' Prozent','aria-pressed':String(selected===k)});path.append(el('title',{},labels[k]+' · '+n+' / '+total));path.addEventListener('click',()=>{selected=k;render();});path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=k;render();}});svg.append(path);if(percent>=7){const t=point(107,(angle+end)/2);svg.append(el('text',{x:t[0],y:t[1]+5,'text-anchor':'middle',fill:k==='open'?'#193445':'white','font-size':18,'font-family':'Arial','font-weight':700,'pointer-events':'none'},String(n)));}angle=end;}
const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(selected===k));button.disabled=!n;const dot=document.createElement('i');dot.style.background=colors[k];const label=document.createElement('span');label.textContent=(k==='open'?'':k+' · ')+labels[k];const count=document.createElement('b');count.textContent=n;const pct=document.createElement('em');pct.textContent=percent.toLocaleString('de-DE',{maximumFractionDigits:1})+' %';button.append(dot,label,count,pct);button.addEventListener('click',()=>{selected=k;render();});legend.append(button);}
svg.append(el('text',{x:160,y:158,'text-anchor':'middle',fill:'#173345','font-size':39,'font-weight':700,'font-family':'Arial'},String(total)));svg.append(el('text',{x:160,y:180,'text-anchor':'middle',fill:'#607887','font-size':12,'font-family':'Arial'},'erfasste Objekte'));
const chosen=selected==='all'?rows:rows.filter(p=>key(p)===selected);document.getElementById('donut-products-title').textContent=(selected==='all'?'Alle Objekte':labels[selected])+' · '+chosen.length;list.replaceChildren();for(const p of chosen){const a=document.createElement('a');a.href='#product-'+p.id;a.style.setProperty('--grade',colors[key(p)]);a.append(document.createTextNode(p.label));const hint=document.createElement('span');hint.textContent='↗';a.append(hint);list.append(a);}if(!chosen.length){const p=document.createElement('p');p.className='meta';p.textContent='Keine Objekte in dieser Auswahl.';list.append(p);}}
domain.addEventListener('change',()=>{selected='all';render();});document.getElementById('donut-all').addEventListener('click',()=>{selected='all';render();});render();})();</script>'''.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
needle='<section class="module"><style>'
assert s.count(needle)==1
s=s.replace(needle,widget+'<section class="module"><details class="matrix-disclosure"><summary>Detaillierte Reife-Matrix & Tabelle</summary><style>',1)
portfolio_js=(B/'references/templates/portfolio.js').read_text()
needle=portfolio_js+'</script></section>'
assert needle in s
s=s.replace(needle,portfolio_js+'</script></details></section>',1)
s=s.replace('</head>',css+'</head>').replace('</body>',js+'</body>')
p.write_text(s)
print(json.dumps({'objects':len(data),'counts':{str(k):sum(x['grade']==k for x in data)for k in [1,2,3,4,5,6,None]},'bytes':len(s.encode())}))
